(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-structural-kv-compress"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-1\">一 · 从一次补全塌陷说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-2\">二 · 它到底解决哪一个问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-3\">三 · 机制：解析、打分、写入、读取、增量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-4\">四 · 失败模式：三种可复现的塌陷路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-5\">五 · 与相邻机制的边界，以及部署判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-6\">六 · 什么时候不该上结构化 KV 压缩：一次工具输出把 TTFT 拖垮的事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-7\">七 · 解析：把连续 token 流切成可寻址的结构区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-8\">八 · 打分：信息密度到压缩率的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-9\">九 · 写入：压缩 KV 落进分页块表并挂元数据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-10\">十 · 解码读取：按标签选精度，避免全量解压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-11\">十一 · 增量更新：新工具输出到达时的局部重压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-12\">十二 · 结构压缩的失效边界与增量代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-13\">十三 · 预算公式的逐项拆解：从权重到块级配额</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-14\">十四 · 区间压缩率映射：密度到 ri 的单调函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-15\">十五 · 锚点保留的伪代码：块内选择与写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-16\">十六 · 增量重压缩的触发条件与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-17\">十七 · 阈值校准与混读一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-18\">十八 · 结构压缩的失效边界与预处理税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-19\">十九 · 请求形态：什么样的负载吃得到结构红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-20\">二十 · 长度分布：预算分配公式在偏斜分布下的行为</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-21\">二十一 · 并发与批大小：块表元数据在连续批处理下的压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-22\">二十二 · 负载不对时：三类可观测的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-23\">二十三 · 配方参数：把负载特征映射到压缩策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-24\">二十四 · 工程判断：负载匹配优先于压缩率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-25\">二十五 · 负载配方：结构压缩在什么请求形态下才划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-26\">二十六 · 硬件档位与压缩预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-27\">二十七 · 并行拓扑：结构区间与 TP/EP 的切分对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-28\">二十八 · 量化方案：按区间分层的精度档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-29\">二十九 · KV 策略：与分页块表共用一套寻址</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-30\">三十 · 调度参数：增量压缩与批处理的时序咬合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-31\">三十一 · 可复现的配置思路：从任务画像反推档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-32\">三十二 · 显存账：压缩率不是均匀红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-33\">三十三 · 带宽账：解码寻址不能引发解压回涨</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-34\">三十四 · 通信账：分离式部署下的压缩不对称</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-35\">三十五 · 功耗与预处理：AST 开销是隐形税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-36\">三十六 · 尾延迟：压缩误差累积与寻址失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-37\">三十七 · 规模上去先崩哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-38\">三十八 · 精度失败：阈值校准错位与结构标签失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-39\">三十九 · OOM 与批抖动：预算公式与真实占用脱节</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-40\">四十 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-41\">四十一 · 监控面：该埋哪些点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-42\">四十二 · 回滚：不可逆压缩下的最小代价路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-43\">四十三 · 结构化压缩的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-44\">四十四 · 对照轴：压缩单元、决策依据与不可逆性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-45\">四十五 · 与分页 KV 块管理的关系：共用块表，不共用预算逻辑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-46\">四十六 · 与注意力驱逐、选择性检索的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-47\">四十七 · 决策表：按输入构成与任务形态选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-48\">四十八 · 适用条件与阈值校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-49\">四十九 · 工程判断：串联顺序与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-structural-kv-compress-sec-50\">五十 · 选型分水岭：结构信号强度与预处理预算</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:558px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 557.5 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对上下文做 AST 解析得到函数、类、导入块等结构单元边界</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按结构单元统计注意力质量与跨块引用关系，计算保留预算</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">块内保留锚点 token（签名、控制流关键字、被引用标识符）的 KV，其余…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">压缩后 KV 与块表重建，解码时按结构单元寻址</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"475.5\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">新工具输出到达时按同一结构策略增量压缩并合并</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-structural-kv-compress-sec-1\">一 · 从一次补全塌陷说起</h3>\n<p>设想一个典型的 agent 编码循环：模型先读入仓库上下文（若干源文件、接口定义、测试），然后连续调用工具——跑测试、读日志、grep 调用点、打补丁——每一轮工具输出都追加进对话，KV cache 单调增长。到第十几轮时，上下文里已经同时存在几千行代码、几百行错误栈和大量自然语言推理。此时 serving 栈的显存水位逼近上限，调度器开始触发通用 KV 压缩：按 token 级注意力分数排序，把低分 token 的 KV 丢弃或量化到低比特。</p>\n<p>事故的表现不是崩溃，而是质量塌陷：模型仍然能写出语法正确的补丁，但开始改错函数——它把某个被调用点的参数顺序记反，或者在一个已经修改过的签名上继续按旧签名生成调用。更糟的是，错误栈里那条指向真实故障点的帧被压掉了，模型转而去修一个无关的辅助函数。工程师看到的是一连串“看起来合理但完全不对”的补全，而日志里没有任何异常。这类故障最难定位，因为压缩本身是静默的，KV 里少了什么不会留下痕迹。</p>\n<p>根因在于压缩单元的粒度与代码语义的粒度不匹配。注意力分数是逐 token 的局部统计量，而代码的依赖关系是结构性的：一个函数签名 token 的注意力分数可能不高（它离当前生成位置很远），但它约束着整个调用链的类型与参数；一个被引用的标识符只在少数几个位置出现，却决定了跨文件推理是否成立。按分数驱逐等于按“当下有多热”而不是按“结构上有多重要”做决策，于是签名、调用点、异常栈这些低热度高价值的区间被优先牺牲。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-2\">二 · 它到底解决哪一个问题</h3>\n<p>结构化 KV 压缩要解决的具体问题是：在 agent 编码循环中，仓库上下文与工具输出把 KV cache 拉到极长，显存容量与带宽成为瓶颈；而代码结构信息分布高度不均，均匀压缩或纯注意力驱逐会把函数签名、调用点、错误栈等关键语义一并压掉，导致跨文件推理失真。注意这个问题的两个半边必须同时成立才有意义——如果上下文不长，压缩无收益；如果结构信息分布均匀，按分数压缩也不会错得离谱。真正需要它的场景是“长 + 结构不均”的交集。</p>\n<p>它不解决的问题同样要划清。第一，它不决定哪些内容该进入上下文——那是检索与门控的职责，本算法只在已经进入上下文的 KV 上分配精度，不改变上下文组成。第二，它不做跨请求的 KV 复用，前缀复用与块管理是另一层的事，这里只借用块表作为压缩表示的载体。第三，它不改善单 token 的数值精度本身，量化档位是它的手段而非目标；它也不解决解码调度的排队问题。第四，它对非代码文本没有结构性抓手——日志、自然语言推理、动态生成的字符串，AST 解析拿不到稳定边界，收益退化为接近均匀压缩。</p>\n<p>因此适用边界可以写得很硬：仓库级长会话、agent 编码循环、上下文以源码与工具结构化输出为主。规模上限由预处理开销约束——上下文越长、工具输出越频繁，AST 解析与区间打分的成本越高，当这部分开销超过压缩省下的显存与带宽收益时，算法整体就是负收益。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-3\">三 · 机制：解析、打分、写入、读取、增量</h3>\n<p>第一步是解析。对输入代码与工具输出做 AST 解析，标注函数边界、导入语句、调用点、异常栈等结构区间，为每个区间打上类型标签。这些标签不是装饰，而是后续精度分配的寻址依据：解码时注意力要知道“这段 KV 属于哪个区间”，才能决定用原始精度还是压缩表示去读。解析发生在预填阶段，与分页块表的建立同步进行。</p>\n<p>第二步是按区间信息密度打分。对每个结构区间估计信息密度，低分区间按块执行 KV 合并或低比特量化，高分区间保留原始精度。这里的关键是压缩单元从单 token 变成区间块：一个函数体内部的局部变量可以整块降精度，而它的签名区间必须原样保留。预算分配写成按区间加权：</p>\n<div class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</div>\n<p>其中 $|K_i|$ 是第 $i$ 个结构区间的 KV 元素数，$r_i$ 是该区间的压缩率，$f$ 把信息密度映射为压缩率，$B$ 是总显存预算；高密度区间取 $r_i\\approx 1$。这个式子的工程含义是：总预算固定时，压缩率不是全局一个数，而是逐区间解出来的，密度估计的误差会直接变成某个区间的精度损失。</p>\n<p>第三步写入分页块表，元数据记录区间类型与压缩率。这一步让它能与现有分页 KV 管理兼容，在 serving 栈上增量实现，而不需要重写内存布局。第四步是解码读取：按结构标签选择读取精度，关键区间走原始 KV，其余走压缩表示；注意力寻址由元数据驱动，避免“先把全部 KV 统一解压再算注意力”这种把带宽收益又吐回去的做法。第五步是增量更新：多轮循环中新工具输出到达时，只对受影响区间重新解析、重新压缩并回写块表，未受影响区间的压缩 KV 保持不变。</p>\n<p>代价分布得很清楚。预处理侧承担 AST 解析与区间统计，属于首 token 时延的一部分；解码侧的收益是显存占用下降与注意力读取带宽下降；增量侧的成本与“每次工具输出触及多少区间”成正比。一个具体例子：一次测试运行返回两百行错误栈，解析把它标为异常栈区间，密度打分给高分，于是这段 KV 保持原始精度，而同一轮里被 grep 出来的大量无关匹配行落在低密度区间，整块量化——显存省在无关行上，精度留给故障帧。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-4\">四 · 失败模式：三种可复现的塌陷路径</h3>\n<p>第一种是预处理开销反噬。AST 解析与区间打分在每次工具输出后都要增量执行，长会话中这一步的累计成本可能超过压缩带来的显存收益，表现为首 token 时延反而上升。判断信号很直接：当单轮工具输出触发的重压缩区间数接近全量时，增量机制已经退化为全量重算，此时应放宽触发条件或按区间类型设置重压缩白名单，而不是继续加大压缩率。</p>\n<p>第二种是阈值校准错位导致的误压。压缩误差在跨文件推理与长距离依赖上累积，若密度阈值按单文件校准而未按仓库任务校准，关键调用点会被误压，补全正确率下降且难以定位——因为被压掉的是一个 token 区间，而不是一条可搜索的日志。工程上的对策是把阈值按任务类型分层：跨文件重构类任务给调用点区间设最低保留精度下限，单文件补全类任务可以更激进。</p>\n<p>第三种是结构标注不稳定。非代码文本或动态生成内容的结构标注不稳定，区间类型标签错乱会使解码时按标签选精度的寻址失效，压缩 KV 与原始 KV 混读造成注意力结果不一致。这类故障的隐蔽性最高：同一段上下文在不同轮次可能被标成不同类型，导致同一位置前后两次解码读到不同精度的 KV，输出出现不可复现的抖动。对策是对低置信区间退回统一精度，宁可多占显存也不让标签驱动寻址。</p>\n<p>还有一条不可逆的代价必须写进设计：压缩不可逆，后续需要被驱逐内容时只能重新预填。这意味着压缩决策是一次性的赌注——当模型在生成中途突然需要引用一个已被量化的远端函数体时，系统没有“解压”选项，只能回退到重新预填该区间，代价是一次额外的预填延迟。因此压缩率的选择必须考虑“未来被引用的概率”，而不只是“当前注意力分数”。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-5\">五 · 与相邻机制的边界，以及部署判断</h3>\n<p>与按 token 位置或注意力分数做非均匀压缩的方案相比，它的压缩单元是 AST 区间块而非单 token，决策依据是结构重要性而非热度；与选择性检索门控相比，它不决定是否检索，而是在已进入上下文的 KV 上分配精度——两者可以串联：门控决定拿什么进来，结构压缩决定进来之后怎么存。与分页块管理的关系是寄生式的：它复用块表，把区间类型与压缩率写进元数据，因此可以在不改动内存管理主干的前提下落地。</p>\n<p>部署配方上有几个硬约束。量化档位按区间分层，关键区间保持原始精度、低密度区间走低比特，KV 以块为单位合并或量化；预处理阶段承担 AST 解析与打分开销，这部分应放在预填流水线里与块表构建并行，而不是串行追加。稳定性技巧是压缩阈值按任务校准：跨文件推理与长距离依赖上压缩误差会累积，需按任务类型设定密度阈值与最低保留精度。硬件档位与并行拓扑在本算法层面不构成约束，因为它改变的是 KV 的表示与寻址，而不是计算图。</p>\n<p>最后一个工程判断落在预算公式的权重上。若把区间预算写成 $\\text{budget}_b=\\frac{B\\cdot w_b}{\\sum_{b'}w_{b'}}$，权重 $w_b=\\alpha\\cdot\\text{attn}_b+\\beta\\cdot\\text{ref}_b+\\gamma\\cdot\\text{size}_b^{-1}$，那么 $\\beta$ 项（跨块引用关系）就是结构压缩区别于纯注意力压缩的全部价值所在：把 $\\beta$ 调大，签名与调用点的保留优先级上升，显存节省变少但跨文件正确率更稳；把 $\\beta$ 调到零，算法退化为按注意力分数压缩，事故里的那种塌陷就会重现。这个系数的选择不是超参调优，而是对“这个仓库的推理有多依赖跨文件引用”的直接编码。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-6\">六 · 什么时候不该上结构化 KV 压缩：一次工具输出把 TTFT 拖垮的事故</h3>\n<p>某仓库级 agent 编码循环在连续批处理下运行，每轮工具调用都会把编译日志、测试输出与检索到的源文件追加进上下文。团队为压显存接入了按注意力分数驱逐的通用 KV 压缩，显存确实降下来了，但补全开始出现一类难以定位的退化：函数签名还在，跨文件的调用点却被丢掉，模型给出的修复引用了不存在的参数顺序。根因不在压缩率，而在压缩单元——单 token 注意力分数无法表达“这个标识符被另一个文件引用”这种结构事实，均匀驱逐把稀疏但关键的语义一并压掉。结构化 KV 压缩正是为这个问题设计的：把压缩单元从单 token 换成 AST 区间块，按结构重要性而非注意力分数分配预算，块内保留签名、控制流关键字与被引用标识符的锚点 KV。它不解决另一类问题——当输入主要是日志、自然语言或动态生成内容时，结构信号本身就弱，区间类型标签不稳定，此时它的收益会退化到与普通分块压缩相当，而预处理开销照付。</p>\n<p>预算分配可以写成按区间加权的形式，其中 $|K_i|$ 为第 $i$ 个结构区间的 KV 元素数，$r_i$ 为该区间压缩率，$f$ 把区间信息密度映射为压缩率：</p>\n<div class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</div>\n<p>高密度区间取 $r_i\\approx 1$ 保留原始精度，低密度区间走块级合并或低比特量化。代价结构必须看清：AST 解析与区间打分在每次工具输出后都要增量执行，长会话中这部分预处理开销可能超过压缩省下的显存收益，表现为首 token 时延不降反升；压缩不可逆，被驱逐区间若在后续轮次被引用，只能重新预填。下表给出三类输入的边界判断。</p>\n<table class=\"mini\"><thead><tr><th>输入形态</th><th>结构信号</th><th>主要代价</th><th>判断</th></tr></thead><tbody><tr><td>仓库源码 + 工具输出</td><td>强，AST 边界清晰</td><td>增量解析与重压缩开销</td><td>适用，需按仓库任务校准密度阈值</td></tr><tr><td>编译/测试日志为主</td><td>弱，异常栈区间有限</td><td>预处理开销照付、收益下降</td><td>仅对异常栈等少数区间启用</td></tr><tr><td>动态生成代码</td><td>不稳定，标签易错乱</td><td>按标签选精度失效、混读不一致</td><td>不适用，退回统一精度或纯分页管理</td></tr></tbody></table>\n<p>失效条件集中在阈值校准上：若密度阈值按单文件校准而未按仓库任务校准，压缩误差会在跨文件推理与长距离依赖上累积，关键调用点被误压后补全正确率下降且难以定位；区间类型标签一旦错乱，解码时按标签选精度的寻址就会失效，压缩 KV 与原始 KV 混读造成注意力结果不一致。因此适用边界应明确为仓库级长会话与 agent 编码循环，规模上限由 AST 解析与区间打分的预处理成本约束——上下文越长、工具输出越密，增量重压缩越贵。工程判断是：先把压缩预算集中在异常栈、导入块与调用点这三类区间，其余区间维持分页管理不动，用块表元数据驱动寻址，避免对全部 KV 统一解压带来的带宽回涨。</p>\n<h3 id=\"alg-structural-kv-compress-sec-7\">七 · 解析：把连续 token 流切成可寻址的结构区间</h3>\n<p>结构化 KV 压缩的第一步不是压缩，而是建立寻址坐标系。输入是请求到达时已进入上下文的全部 token——仓库文件片段、历史对话、工具返回的编译错误或测试输出；输出是一张区间表，每个区间带类型标签（函数体、类定义、导入块、调用点、异常栈帧、自然语言注释、日志行）与起止 token 偏移。实现上对代码段走 AST 解析器，对工具输出按行首模式匹配（如 <code>File \"x.py\", line N</code> 的栈帧格式）做轻量标注，两者合并成统一区间序列。</p>\n<p>这一步的代价是纯 CPU 预处理，落在请求进入调度器之后、prefill 之前。它的关键工程性质是<strong>与 token 数近似线性但常数不小</strong>：AST 解析要构建语法树再遍历取边界，比单纯分词贵一个量级。对一次仓库级 agent 会话，上下文可达数十万 token，解析开销直接计入首 token 时延（TTFT）。因此实现上必须做两件事：其一，对同一文件内容的重复出现走内容哈希缓存，命中则复用区间表；其二，把解析放在独立线程池并与 tokenize 流水线重叠，使解析延迟被 prefill 的 GEMM 时间吸收。若解析串行阻塞在关键路径上，压缩省下的显存换来的吞吐增益会被 TTFT 上升抵消。</p>\n<p>区间表的粒度选择是设计决策而非实现细节。粒度过细（每个表达式一个区间）使元数据膨胀、块表项数暴涨，解码寻址的间接层开销上升；粒度过粗（整个文件一个区间）则丧失按结构分配预算的意义。工程上的折中是<strong>以函数/类为基本单元，块内再标注锚点 token 偏移</strong>，即两级结构：区间级决定压缩率，锚点级决定哪些 token 必须保精度。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-8\">八 · 打分：信息密度到压缩率的映射</h3>\n<p>第二步对每个区间估计信息密度，输出每区间的压缩率 $r_i$。密度信号由三部分构成：区间内 token 的注意力质量统计（prefill 时各层注意力对该区间的累计权重）、跨块引用关系（该区间定义的标识符是否被其他区间引用、该区间是否包含调用点）、以及区间类型先验（签名与控制流关键字权重高，注释与日志权重低）。三者加权后经单调映射 $f$ 得到压缩率。</p>\n<div class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</div>\n<p>其中 $|K_i|$ 是区间 $i$ 的 KV 元素数，$B$ 是总显存预算。高密度区间取 $r_i\\approx 1$（原始精度、不压缩），低密度区间取低比特量化或块内合并。注意这个式子是<strong>预算约束下的分配问题</strong>而非逐区间独立决策：给定 $B$，需要把有限的“保精度额度”优先给密度最高的区间，等价于按密度排序后贪心填充预算。工程上不必求解精确最优，按密度分档（如三档：原始精度、FP8、更低比特合并）即可，因为档位切换的收益是阶跃的，而求解连续最优带来的额外收益被量化误差掩盖。</p>\n<p>这一步的代价有两块。计算代价：注意力质量统计需要 prefill 阶段的注意力输出，若在 prefill 后异步收集则需保留中间统计量，增加少量显存；若复用已有注意力 logits 则几乎零额外算力，但要求框架暴露该接口。决策代价：打分必须在 prefill 完成、KV 写入之前完成，否则压缩无从下手，这使打分处于关键路径，其延迟与区间数成正比而非与 token 数成正比——这是把粒度做粗的直接动机。</p>\n<p>具体例子：一个含 40 个函数、3 个导入块、若干日志行的仓库上下文，导入块被大量调用点引用，密度打分最高，$r_i=1$；函数签名与控制流关键字作为锚点保精度；函数体内的注释与未被引用的局部变量区间密度低，走低比特。这样在同等显存下，跨文件调用链的语义不被压掉。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-9\">九 · 写入：压缩 KV 落进分页块表并挂元数据</h3>\n<p>第三步把压缩后的 KV 写入分页块表，并在块表项上挂两个字段：区间类型标签与压缩率。写入路径与常规 paged KV 完全一致——按块分配物理页、写 KV 数据、更新块表映射——差别只在块表项多出的元数据，以及部分块内 KV 已被量化或合并。这意味着<strong>它可以在现有 serving 栈上增量实现</strong>，不需要替换分配器，只需在块表结构上扩展字段、在写入前插入压缩 kernel。</p>\n<p>写入阶段的代价主要在带宽与 kernel 启动。压缩本身要读原始 KV、写压缩 KV，若压缩率是 4 倍，写入带宽降为四分之一，但读取原始 KV 的带宽不变，因此净带宽节省取决于压缩比与是否原地操作。块内合并（把多个 token 的 KV 合成一个代表向量）需要跨 token 归约，属于带宽受限 kernel；低比特量化则是逐元素变换，属于计算轻、带宽重的 kernel。两者都应按块并行、与 prefill 的后续层计算重叠，否则写入成为串行尾巴。</p>\n<p>元数据设计决定解码期的寻址成本。若每个块表项存区间标签，解码时注意力对每个块做一次标签判断再选读取路径，判断开销与块数成正比；若把标签编码进块表项的高位、用位运算分支，可把判断压到几条指令。工程判断是：<strong>元数据必须小到能与块表项同 cache line 存放</strong>，否则解码期每次寻址多一次内存访问，长上下文下这个间接层会吃掉压缩带来的带宽收益。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-10\">十 · 解码读取：按标签选精度，避免全量解压</h3>\n<p>第四步是收益兑现的地方。解码时注意力按块表元数据选择读取路径：关键区间走原始 KV，其余区间走压缩表示并在需要时即时解压到寄存器或共享内存。核心约束是<strong>不能对全部 KV 统一解压</strong>——那会把压缩省下的带宽原样还回去，甚至因解压算力而更慢。因此解压必须是按块的、惰性的、且只对当前注意力真正触及的块执行。</p>\n<p>代价结构在这里发生转移：显存容量下降，但解码期多了分支判断与解压算力。对带宽受限的解码阶段（batch 小、算术强度低），减少 KV 读取字节数是主要收益来源，解压算力通常被内存等待掩盖；对算力受限的大 batch 场景，解压算力开始显形，需要评估解压 kernel 是否与 MMA 流水重叠。Blackwell 上 tcgen05 的异步 MMA 与 TMEM 为这种重叠提供了空间：把解压放在 MMA 之前的流水段，用 TMA 预取压缩块，解压结果写入共享内存供 MMA 消费。</p>\n<p>具体机制上的一个陷阱是<strong>混读一致性</strong>：同一注意力头内，部分块走原始精度、部分块走量化表示，两者数值尺度不同，直接拼接会让 softmax 的分母失真。解决办法是在块表项记录量化 scale，读取时统一还原到同一数值域再进入 softmax，或在压缩时保证量化零点对齐。这一步不做，压缩 KV 与原始 KV 混读会造成注意力结果不一致，表现为长上下文下输出漂移而非明显错误，极难定位。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-11\">十一 · 增量更新：新工具输出到达时的局部重压缩</h3>\n<p>第五步针对 agent 循环的本质特征：上下文不是一次写死的，工具输出持续追加。新输出到达时，增量更新结构标注——只解析新增片段、只对受影响区间重新打分与压缩、只回写受影响的块表项，未受影响区间的压缩 KV 保持不变。这控制了重压缩开销，使每轮循环的预处理成本与新增 token 数成正比而非与总上下文成正比。</p>\n<p>“受影响区间”的判定是这一步的技术核心。追加型工具输出（新日志行、新测试结果）通常只新增区间，不影响既有区间；但若新输出改变了跨块引用关系（例如新增代码引用了先前被判为低密度而压缩的标识符），则该标识符所在区间的密度打分需要上调，触发该区间的重压缩。实现上维护一张“标识符→区间”的反向索引，新增引用时查索引定位需重估的区间，把重估范围限制在引用闭包内。</p>\n<p>代价与失败模式在此叠加。每次工具输出后都要增量执行解析与打分，长会话中这些预处理开销可能超过压缩带来的显存收益，导致首 token 时延反而上升——这是该机制最现实的部署风险，缓解手段是解析缓存、异步化、以及对纯追加型输出走快速路径跳过重打分。另一失败模式是压缩不可逆：被驱逐的内容若后续需要，只能重新预填，重新预填的代价是一次完整 prefill 的算力与延迟，在长上下文下不可忽略。因此驱逐策略应偏保守，宁可多留低比特表示也不轻易整块丢弃。</p>\n<p>阈值校准是稳定性抓手：密度阈值若按单文件校准而未按仓库任务校准，跨文件推理与长距离依赖上的压缩误差会累积，关键调用点被误压，补全正确率下降且难以定位。工程上应按任务类型（补全、修复、跨文件重构）分别设定密度阈值与最低保留精度，并在非代码文本占比高的会话中降低结构压缩的权重——结构标注在日志与自然语言上不稳定，标签错乱会使解码期按标签选精度的寻址失效。</p>\n\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>解析</td><td>代码与工具输出 token</td><td>区间表＋类型标签</td><td>CPU 预处理，计入 TTFT</td></tr><tr><td>打分</td><td>区间表＋注意力统计＋引用图</td><td>每区间压缩率 $r_i$</td><td>关键路径延迟，与区间数成正比</td></tr><tr><td>写入</td><td>原始 KV＋$r_i$</td><td>压缩 KV＋块表元数据</td><td>读原始 KV 带宽、压缩 kernel</td></tr><tr><td>解码读取</td><td>块表元数据＋查询</td><td>按块解压的 KV</td><td>分支判断＋解压算力，需与 MMA 重叠</td></tr><tr><td>增量更新</td><td>新工具输出</td><td>局部重压缩后的块表</td><td>重压缩开销随会话增长累积</td></tr></tbody></table>\n\n<p>把五步串起来看，工程判断落在两处：解析与打分的预处理必须与 prefill 计算重叠并被内容缓存吸收，否则压缩在长会话中得不偿失；块表元数据必须与块表项同 cache line 且解码解压按块惰性执行，否则寻址间接层与全量解压会把带宽收益还回去。这两处决定了结构化压缩在 Blackwell serving 栈上是净增益还是净负担。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-12\">十二 · 结构压缩的失效边界与增量代价</h3>\n<p>这套机制并非在所有输入上都成立。AST 解析与区间打分在每次工具输出到达后都要增量执行，而 agent 编码循环的工具输出往往短、碎、频繁，第五步的增量重压缩本身有固定成本：解析新片段、重算受影响区间的密度、回写块表元数据。长会话中这部分预处理开销会与压缩带来的显存收益竞争，当工具输出频率高而单次输出信息量低时，预处理甚至可能拖长首 token 时延。规模上限因此不取决于显存，而取决于解析与打分的吞吐——上下文越长、工具输出越多，增量成本越高。更隐蔽的失效在阈值校准：密度阈值若按单文件校准而非按仓库任务校准，跨文件调用点会被判为低密度区间而误压，压缩误差在长距离依赖上累积，补全正确率下降且难以定位到具体区间。</p>\n<p>预算分配公式本身也暴露了边界。按区间加权的压缩预算为</p>\n<div class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</div>\n<p>其中高密度区间取 $r_i\\approx 1$ 保留原始精度。问题在于 $f$ 的单调性依赖 density 估计的可信度：非代码文本（日志、自然语言工具返回、动态生成内容）的结构信号弱，区间类型标签容易错乱，一旦标签错位，解码时按标签选精度的寻址就失效，压缩 KV 与原始 KV 混读会直接造成注意力结果不一致，而不是温和的质量退化。这类错误不会以显存指标报警，只以补全错误率的形式出现。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>代价落点</th></tr></thead><tbody><tr><td>工具输出高频碎片化</td><td>增量重压缩排队</td><td>首 token 时延上升</td></tr><tr><td>阈值按单文件校准</td><td>跨文件调用点被误压</td><td>补全正确率下降</td></tr><tr><td>非代码文本占比高</td><td>区间标签错乱、混读</td><td>注意力结果不一致</td></tr><tr><td>后续需被驱逐内容</td><td>压缩不可逆</td><td>只能重新预填，带宽与算力回涨</td></tr></tbody></table>\n<p>最后一条最容易被低估：压缩不可逆，被驱逐区间的原始 KV 不再存在，一旦后续推理需要该内容（例如修复任务回读到早前工具输出），唯一手段是重新预填，代价是整段上下文的 prefill 算力与 HBM 带宽重新支付，在 NVL72 这类高带宽机架上仍会打断连续批处理的节奏。工程判断是：把结构压缩当作有损缓存而非无损压缩来调度，对可回读的仓库上下文允许激进压缩，对一次性工具输出保留最低精度下限，并按任务类型而非单文件设定密度阈值；当非结构化输入占比升高时，应主动退回均匀压缩或纯注意力驱逐，而不是让错乱的标签继续驱动寻址。</p>\n<h3 id=\"alg-structural-kv-compress-sec-13\">十三 · 预算公式的逐项拆解：从权重到块级配额</h3>\n<p>结构化 KV 压缩的分配公式写成两层：先算结构单元的相对权重，再把总预算按权重切分。</p>\n<div class=\"formula\">$$\\text{budget}_b=\\frac{B\\cdot w_b}{\\sum_{b'}w_{b'}},\\quad w_b=\\alpha\\cdot\\text{attn}_b+\\beta\\cdot\\text{ref}_b+\\gamma\\cdot\\text{size}_b^{-1}$$</div>\n<p>这里 <em>b</em> 遍历的是 AST 解析得到的结构单元——函数、类、导入块、异常栈区间，而不是 token 位置。<span>attn<sub>b</sub></span> 是该单元内 token 注意力质量的聚合（对块内 token 的注意力分数做质量加权求和，而非取最大单点值，避免一个尖峰 token 绑架整个函数的预算）；<span>ref<sub>b</sub></span> 是跨块引用计数，即该单元被其他结构单元引用的次数，这是纯注意力驱逐完全看不到的信号——一个被十个文件调用的工具函数，其签名 token 的单点注意力可能很低，但删掉它会让下游所有调用点的语义悬空；<span>size<sub>b</sub><sup>-1</sup></span> 是对大块的惩罚项，防止一个巨型文件凭体量吃掉全部预算。三个系数 α、β、γ 是任务级校准量，跨文件推理任务要把 β 调高，单文件补全可以把 γ 调高。</p>\n<p>推导的关键一步在于：预算必须可加且守恒。把 <span>w<sub>b</sub></span> 归一化后乘以总预算 <em>B</em>，得到每块的 KV 元素配额；由于 <span>budget<sub>b</sub></span> 直接以元素数为单位，它可以直接落到分页块表的块粒度上——一个结构单元的配额向上取整到块边界，余量并入相邻块。这一步把\"结构重要性\"翻译成了\"显存地址空间\"，是公式能进 serving 栈的前提。工程代价上，配额守恒意味着总显存占用严格不超过 <em>B</em>，但块边界取整会带来不超过一个块大小的碎片浪费；在长仓库上下文下，碎片占比随块尺寸增大而上升，因此块尺寸的选择要与结构单元的平均长度匹配。</p>\n<p>具体例子：一个 200 块的仓库上下文，某工具函数块 <span>attn<sub>b</sub></span> 中等、<span>ref<sub>b</sub></span> 极高（被 12 个调用点引用）、<span>size<sub>b</sub></span> 很小，其权重在 β 主导下排进前列，配额足以保留全部签名与控制流关键字 token 的原始 KV；而一个体量巨大但无引用的日志粘贴块权重被 <span>size<sub>b</sub><sup>-1</sup></span> 压低，配额只够保留少量锚点，其余走低比特。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-14\">十四 · 区间压缩率映射：密度到 r<sub>i</sub> 的单调函数</h3>\n<p>第二层公式是区间级的压缩率分配：</p>\n<div class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</div>\n<p><span>|K<sub>i</sub>|</span> 是第 <em>i</em> 个结构区间的 KV 元素数，<span>r<sub>i</sub></span> 是该区间的压缩率（1 表示原始精度不压缩，越小压得越狠），<em>B</em> 是总显存预算。<em>f</em> 必须是单调递减函数：密度越高，压缩率越接近 1。工程上 <em>f</em> 取分段阶梯而非连续函数——因为量化档位是离散的（原始精度、低比特、块合并），连续映射最后仍要落到档位上，分段阶梯可以避免同一区间在两个档位间抖动导致重压缩。阶梯的断点就是\"密度阈值\"，也是稳定性技巧里要按任务校准的那个量。</p>\n<p>推导的关键一步是把预算守恒条件从块级转到区间级：给定各区间 <span>|K<sub>i</sub>|</span> 与密度，求一组 <span>r<sub>i</sub></span> 使 Σ<span>r<sub>i</sub>|K<sub>i</sub>|</span> ≤ <em>B</em>。做法是自高密度区间向下贪心：先令所有高密度区间 <span>r<sub>i</sub></span>=1 并扣除其占用，剩余预算再按密度降序分配给中低密度区间，直到预算耗尽，尾部区间压到最低档。贪心的正确性依赖于 <em>f</em> 的单调性——高密度区间先拿满不会挤占更高密度的区间，因为排序已保证优先级。代价在于贪心是离线一次算完的，增量更新时若新工具输出改变了密度排序，已分配的档位可能不再最优，需要局部重排而非全局重算。</p>\n<p>具体例子：异常栈区间密度最高，<span>r<sub>i</sub></span>=1，原始 KV 全保留；函数签名区间次高，同样取 1；函数体内部低密度 token 取低比特档；纯注释与空白区间取块合并档。这样在同等 <em>B</em> 下，精度集中到了签名、控制流关键字与被引用标识符上，而这些正是解码时按结构标签寻址要读的锚点。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-15\">十五 · 锚点保留的伪代码：块内选择与写回</h3>\n<p>预算与压缩率定完后，落到可实现层面是块内的锚点选择。思路如下（伪代码，非 <pre>）：对每个结构单元，先按锚点规则标记必留 token——签名 token、控制流关键字、被引用标识符；这些 token 的 KV 强制走原始精度并计入该块配额。剩余配额按注意力质量降序填充非锚点 token，填满即止，未入选的 token 按区间压缩率走低比特或块合并。写回时每个分页块携带元数据：区间类型标签、压缩率、锚点位图。解码时注意力按元数据选择读取精度，锚点走原始 KV，其余走压缩表示，避免对整块统一解压带来的带宽回涨。</p>\n<p>这里的关键工程判断是锚点集合的粒度：锚点按 token 标记而非按块标记，因为一个函数块的签名只占块首若干 token，若整块按原始精度读，等于把函数体也抬到了高精度，预算立刻失控。锚点位图使读取路径可以只解压非锚点部分，代价是读取时的分支判断增加，在带宽受限场景下这笔开销远小于全块解压。另一个代价是元数据本身的显存：每个块多出若干字节的标签与位图，在块数量极大时不可忽略，需要与块表共用同一页结构以摊薄。</p>\n<p>具体例子：一个类定义块，锚点是类名、继承列表、方法签名三类 token；块内其余方法体 token 按预算压缩。解码时若当前生成位置在调用该类的方法，注意力只需读锚点原始 KV 即可恢复类型与签名语义，方法体走压缩表示，单次读取的字节数下降而语义不丢。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-16\">十六 · 增量重压缩的触发条件与代价核算</h3>\n<p>多轮 agent 循环里，新工具输出到达时不能全局重压缩。增量策略是：只对受影响的区间重新解析、重新打分、重新压缩并回写块表，未受影响区间的压缩 KV 保持不变。触发条件由结构标注的变更检测给出——新输出若落在已有区间内且未改变区间边界，只更新该区间的密度与压缩率；若引入了新的结构单元（新文件、新函数），则为新单元分配预算并从尾部低密度区间回收配额。</p>\n<p>代价核算必须诚实：AST 解析与区间打分在每次工具输出后都要增量执行，长会话中预处理开销可能超过压缩带来的显存收益，导致首 token 时延反而上升。这是本算法最现实的失败模式。缓解手段是把解析限制在变更窗口内（只解析新输出及其直接引用者），并把密度打分做成可缓存的——区间密度在无结构变更时可复用上次结果。另一个代价是压缩不可逆：被驱逐的区间若后续被引用，只能重新预填，这笔预填成本要计入容量规划，而不是当作零成本回退。</p>\n<p>具体例子：agent 连续执行五次工具调用，每次输出追加到同一日志区间。若每次都对整个日志区间重压缩，预处理时间随会话线性增长；按变更窗口增量处理后，只有日志区间的尾部被重新打分，前四次已压缩的 KV 原样保留，首 token 时延不随轮次累积。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-17\">十七 · 阈值校准与混读一致性</h3>\n<p>密度阈值按任务校准，而不是按单文件校准。跨文件推理与长距离依赖上压缩误差会累积：若阈值按单文件调优，在仓库级任务里关键调用点会被误压，补全正确率下降且难以定位——因为错误表现为跨文件语义断裂，而非单点 token 错误。校准的做法是分层设阈值：跨文件引用密度高的区间用更保守的阈值（更少压缩），单文件内部区间可以用更激进的阈值。最低保留精度也要按区间类型设下限，防止某类区间被压到无法恢复语义的档位。</p>\n<p>混读一致性是另一个必须处理的工程点。解码时按结构标签选精度，若区间类型标签错乱——非代码文本或动态生成内容的结构标注不稳定——压缩 KV 与原始 KV 会混读，注意力结果不一致。防护手段是在块表元数据里记录压缩率与实际存储格式，读取路径以元数据为准而非以标签推断；标签只用于预算分配，不直接决定读取精度。这样即使标签错乱，读取仍按实际存储格式解压，一致性由元数据保证。</p>\n<p>具体例子：工具输出里混入一段自然语言错误说明，AST 解析给它一个不稳定的区间标签。若读取路径信标签，可能把这段按高精度读而实际存的是压缩表示，混读导致注意力分数偏移；以元数据为准后，读取按实际压缩率解压，标签错乱只影响预算分配的次优性，不影响数值一致性。</p>\n<p>最后落在机制上：结构化 KV 压缩的可行性不取决于公式多漂亮，而取决于预算守恒能否落到块粒度、锚点位图能否让读取路径只解压必要部分、增量重压缩能否把预处理开销压在变更窗口内。三者任一失守，显存收益都会被时延或一致性代价吃掉。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-18\">十八 · 结构压缩的失效边界与预处理税</h3>\n<p>这套方案把压缩预算写成区间加权和：<div class=\"formula\">$$B=\\sum_{i} r_i\\cdot|K_i|,\\quad r_i=f(\\text{density}_i)$$</div>其中 $|K_i|$ 是第 $i$ 个 AST 区间的 KV 元素数，$r_i$ 是该区间的压缩率，$f$ 把信息密度映射为压缩率，高密度区间取 $r_i\\approx1$。推导的关键一步在于：$f$ 不是连续可调的旋钮，而是带阈值的阶梯函数——密度低于阈值的区间整体落入低比特或块合并档，高于阈值的区间保持原始精度。于是误差不随预算平滑变化，而是在阈值附近发生跳变：一个调用点从“保留”跨到“压缩”只差一点密度分数，注意力结果却从精确变为有损。这意味着按单文件校准的阈值在仓库级任务上必然偏激，跨文件的长距离依赖会让压缩误差沿调用链累积，补全正确率下降且难以定位到具体区间。</p>\n<p>系统代价的大头不在显存而在预处理。每次工具输出到达都要增量执行 AST 解析与区间打分，只对受影响区间重压缩并回写块表——这一步省掉了全量重算，但解析本身无法增量跳过：新输出的语法边界可能改写已有区间的划分，块表元数据（区间类型、压缩率）需要同步刷新。长会话中工具输出密集，预处理开销可能超过压缩换来的显存收益，首 token 时延反而上升。工程判断是给预处理设硬预算：单次增量压缩的解析时间超过解码首 token 预算的一定比例时，退化为“只标注不重压”，把新输出按保守精度直接写入，等空闲窗口再补压缩。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>表现</th><th>代价落点</th></tr></thead><tbody><tr><td>非代码文本占比高（日志、自然语言）</td><td>结构标签错乱，按标签选精度失效</td><td>压缩 KV 与原始 KV 混读，注意力结果不一致</td></tr><tr><td>阈值按单文件校准</td><td>关键调用点被误压</td><td>跨文件推理误差累积，正确率下降</td></tr><tr><td>工具输出高频到达</td><td>增量解析与打分排队</td><td>首 token 时延上升，显存收益被抵消</td></tr></tbody></table>\n<p>还有一层不可逆代价必须写进调度策略：压缩后的 KV 无法还原，一旦后续轮次需要被驱逐的区间内容（例如 agent 回头引用早先的工具输出），只能重新预填该区间，代价是一次局部的 prefill 而非一次读取。因此块表元数据里应记录每个区间的“可重填成本”，调度器在显存紧张时优先压缩重填成本低的区间，把重填代价高的区间（错误栈、跨文件调用点）钉在原始精度上。这与按 token 位置或注意力分数做非均匀压缩的相邻算法形成分工：后者不依赖结构信号，在非代码输入上更稳；本方案的优势区间是仓库级长会话，输入越结构化收益越大，非结构化占比升高时应当降级为纯分页管理而非强行套用结构标签。</p>\n<h3 id=\"alg-structural-kv-compress-sec-19\">十九 · 请求形态：什么样的负载吃得到结构红利</h3>\n<p>结构化 KV 压缩的收益不是均匀分布的，它依赖请求里存在<strong>可解析、可复用的结构区间</strong>。适配的请求形态有三类：仓库级补全（上下文是若干文件加导入链）、agent 工具循环（每轮追加工具输出、错误栈、diff）、多轮修复会话（同一文件被反复读改）。这三类的共同点是上下文长、结构单元边界清晰、跨块引用关系稳定——AST 解析一次能覆盖大量 token，区间标签在若干轮内不变，压缩预算按结构分配才有意义。</p>\n<p>反过来，短请求是结构压缩的净亏损区。一次几百 token 的单函数问答，AST 解析与区间打分的固定开销摊到极短的 KV 上，预处理时间占比压过显存节省。工程判断很简单：设上下文长度为 <span class=\"formula-inline\">L</span>、预处理开销为 <span class=\"formula-inline\">T<sub>pre</sub></span>、压缩带来的解码带宽节省为 <span class=\"formula-inline\">ΔT<sub>dec</sub></span>，只有当 <span class=\"formula-inline\">ΔT<sub>dec</sub> &gt; T<sub>pre</sub></span> 时该请求才值得走结构路径。因此配方上应设长度门槛，短于门槛的请求直接走原始 KV 或均匀量化，把结构压缩留给长会话。</p>\n<p>请求形态还决定压缩单元的有效粒度。补全类请求以文件为外层、函数为内层，压缩预算应下沉到函数块；agent 循环以工具调用为外层、输出片段为内层，预算应挂在调用点上。同一套 AST 区间机制，外层切分不同，块表元数据的组织方式就不同——这是配方层面必须先定的第一件事。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-20\">二十 · 长度分布：预算分配公式在偏斜分布下的行为</h3>\n<p>结构压缩的预算分配沿用按区间加权的形式：</p>\n<div class=\"formula\">$$\\text{budget}_b=\\frac{B\\cdot w_b}{\\sum_{b'}w_{b'}},\\quad w_b=\\alpha\\cdot\\text{attn}_b+\\beta\\cdot\\text{ref}_b+\\gamma\\cdot\\text{size}_b^{-1}$$</div>\n<p>其中 <span class=\"formula-inline\">ref<sub>b</sub></span> 是该结构块被其他块引用的次数，<span class=\"formula-inline\">size<sub>b</sub><sup>-1</sup></span> 抑制超大块（如自动生成的巨型类）独占预算。真实仓库的长度分布是重尾的：少数文件占据大部分 token，大量小文件只贡献签名与导入。重尾分布下 <span class=\"formula-inline\">size<sub>b</sub><sup>-1</sup></span> 项的作用被放大——若去掉它，几个大文件会吞掉几乎全部预算，小文件里的调用点被压到低比特，跨文件引用恰好断在这些点上。</p>\n<p>长度分布还影响增量压缩的成本曲线。agent 循环里每轮工具输出追加的长度不等，若单轮追加量远小于已有上下文，增量压缩只触碰受影响区间，开销可控；若单轮追加量接近甚至超过已有上下文（例如一次全仓库 grep 输出），受影响区间覆盖大半块表，增量退化为近似全量重压缩，首 token 时延抬升。配方上应对单轮追加量设监控，超过上下文一定比例时改为延迟压缩或分片压缩，避免在关键路径上做全量 AST 重解析。</p>\n<p>另一个分布特征是<strong>结构密度随长度衰减</strong>：上下文越长，日志、自然语言说明、重复输出的占比越高，可解析结构区间占比越低。这意味着压缩率不能按固定阈值给，而要随非结构化占比动态收紧——非结构化段走更激进的低比特或合并，把省下的预算让给结构化段。显存收益主要来自这部分非结构化长尾，而不是来自压缩代码本身。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-21\">二十一 · 并发与批大小：块表元数据在连续批处理下的压力</h3>\n<p>结构压缩与分页 KV 管理共用块表，解码时按区间类型标签选读取精度。连续批处理把不同请求的块拼进同一批，问题随之而来：同一批内不同请求的区间标签集合不同，注意力核需要按请求分别寻址，元数据读取从“每请求一次”变成“每请求每层一次”。批越大，元数据带宽占比越高；当批内请求的压缩率分布很散（有的请求几乎全原始精度、有的几乎全低比特），核内分支与地址计算的开销会吃掉压缩省下的显存带宽。</p>\n<p>配方上的对策是<strong>按压缩档位分桶调度</strong>：把压缩率相近的请求放进同一批，减少批内精度混读。代价是调度器要多维护一个档位维度，且桶内请求长度差异可能变大，批内 token 数不均衡会拉低利用率。工程上要在“批内精度一致性”和“批内长度均衡”之间取折中，通常以档位为主维度、长度为次维度。</p>\n<p>并发上升还会暴露块表的写冲突。增量压缩在工具输出到达时回写块表，若同一请求的多个解码步与压缩步交错，块表条目需要版本号或写时复制，否则解码读到半压缩状态会造成注意力结果不一致。这是并发配方里最容易被忽略的一条：压缩不是离线预处理，它在服务路径上持续发生，块表必须是并发安全的。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-22\">二十二 · 负载不对时：三类可观测的退化</h3>\n<p><strong>退化一，预处理开销反超显存收益。</strong>AST 解析与区间打分在每次工具输出后增量执行，长会话中轮次多、追加频繁，预处理累计时间可能超过压缩带来的解码加速，首 token 时延反而上升。可观测信号是预处理时间占端到端时延的比例持续爬升，而显存占用下降趋缓。此时应降低重压缩频率，把区间标签做成惰性更新。</p>\n<p><strong>退化二，压缩误差沿跨文件依赖累积。</strong>若密度阈值按单文件校准而非按仓库任务校准，关键调用点会被误压，补全正确率下降且难以定位——错误不表现为语法错，而表现为语义漂移（调用了错误的重载、漏掉异常分支）。这类退化在指标上表现为补全通过率缓降而非骤降，排查成本高。配方上必须按任务类型设定密度阈值与最低保留精度，跨文件推理任务给关键区间留原始精度。</p>\n<p><strong>退化三，结构标注不稳定导致寻址失效。</strong>非代码文本或动态生成内容（模板渲染、运行时拼接的代码）结构信号弱，区间类型标签错乱，解码时按标签选精度的寻址把压缩 KV 与原始 KV 混读，注意力结果不一致。可观测信号是同一请求在不同轮次间输出抖动变大。对策是对标注置信度低的区间退回统一精度，不强行套结构标签。</p>\n<p>三类退化共享一个根因：压缩不可逆。被驱逐的内容后续需要时只能重新预填，重预填的代价在长仓库上下文下极高。因此配方上应保留“可重预填”的逃生通道——块表记录被压缩区间的原始位置，必要时按需回填，而不是把压缩当成一次性丢弃。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-23\">二十三 · 配方参数：把负载特征映射到压缩策略</h3>\n<p>把上述观察收敛成一组可调参数，配方大致是四维的：长度门槛（低于则不走结构路径）、结构化占比阈值（低于则收益不足，退回均匀量化）、单轮追加比例上限（超过则延迟或分片压缩）、档位分桶粒度（决定批内精度一致性）。四者互相牵制：门槛放低会让短请求承担预处理开销，占比阈值放低会让非结构化负载白付解析成本，追加比例上限放宽会让增量退化为全量。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>配方动作</th><th>主要代价</th></tr></thead><tbody><tr><td>上下文短、结构单元少</td><td>跳过结构压缩，走原始 KV 或均匀量化</td><td>放弃潜在显存收益</td></tr><tr><td>结构化占比高、引用密集</td><td>关键区间原始精度，长尾低比特</td><td>预处理与打分开销</td></tr><tr><td>单轮追加量巨大</td><td>延迟压缩或分片增量</td><td>首 token 时延抬升</td></tr><tr><td>压缩率分布散</td><td>按档位分桶调度</td><td>批内长度不均衡</td></tr><tr><td>标注置信度低</td><td>该区间退回统一精度</td><td>局部显存不降</td></tr></tbody></table>\n<p>参数校准应绑定任务而非绑定模型：跨文件推理任务把密度阈值调高、最低保留精度调高；单文件补全任务可以更激进。校准数据来自线上请求的结构化占比与补全通过率的联合分布，而不是离线固定阈值。阈值过激的失败模式是明确的——关键调用点被误压，补全正确率下降且难以定位，所以任何激进档位都必须配一条回退路径。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-24\">二十四 · 工程判断：负载匹配优先于压缩率</h3>\n<p>结构化 KV 压缩在服务栈上的定位是“长会话的显存与带宽杠杆”，不是通用压缩器。把它套到短请求或非结构化负载上，收益会被预处理开销吃掉；把它套到跨文件密集引用的仓库任务上而不校准阈值，误差会沿依赖链累积。配方设计的核心不是追求最高压缩率，而是判断当前负载是否落在结构信号强、上下文长、引用稳定的区间内。</p>\n<p>具体机制上，落地时最该盯住的是块表元数据的两件事：区间类型标签的置信度，以及增量压缩的版本一致性。前者决定解码寻址是否有效，后者决定并发下注意力结果是否一致。这两项做稳，压缩率才有意义；做不稳，压缩率越高，退化越隐蔽。负载不对时的正确动作是退回均匀策略并保留重预填通道，而不是继续加码结构压缩。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-25\">二十五 · 负载配方：结构压缩在什么请求形态下才划算</h3>\n<p>这套方案的经济性完全取决于「结构信号密度」与「预处理摊销比」。它天然适配仓库级长会话的 agent 编码循环：单请求上下文里同时挂着仓库快照、多轮工具输出与对话历史，KV 长度被拉到远超单文件补全的量级，而其中函数签名、导入块、调用点、异常栈这些区间恰好是高价值低体积的部分。反过来，短请求（单文件补全、单轮问答）或非代码占比高的负载（日志流、自然语言检索结果、动态生成内容）是它的失效区——AST 解析与区间打分在每次工具输出后都要增量执行，当上下文短到压缩省下的显存不足以覆盖解析开销时，首 token 时延反而上升。可用一条粗略的判据刻画盈亏平衡：设单次预处理代价为 $c_p$（随区间数与工具输出频次增长），压缩带来的单请求显存节省为 $\\Delta M$，则只有当 $\\Delta M$ 足以把并发批大小从 $b$ 抬到 $b'$、且吞吐增益覆盖 $c_p$ 时，方案才成立；在长会话里 $\\Delta M$ 随上下文线性增长而 $c_p$ 只随新增区间增长，两者拉开差距，短会话里则相反。</p>\n<p>长度分布的形状比平均长度更重要。压缩预算按区间分配 $B=\\sum_i r_i\\cdot|K_i|,\\ r_i=f(\\text{density}_i)$，高密度区间取 $r_i\\approx1$，这意味着收益来自「大量低密度区间被压到低比特」这一长尾结构。若请求长度分布集中在中等长度、且区间类型单一（例如整段都是同一个大函数体），可压缩的低密度区间少，显存下降有限，而块表元数据与按标签寻址的读取分支仍要付出代价。并发与批大小上，它和分页 KV 管理共用块表，压缩后的 KV 以块为单位合并或量化，因此批内不同请求的区间类型分布越杂，解码时按结构标签选精度的寻址分支越难合并成整齐的批量读，带宽利用率下降；同构负载（同一仓库、同类任务）反而能吃满收益。部署配方上应按任务类型校准密度阈值与最低保留精度，跨文件推理任务给更保守的阈值，单文件任务可放宽。</p>\n<p>负载不对时的失效是可观测的，且往往以「质量下降但难以定位」的形式出现。第一类是阈值按单文件校准而未按仓库任务校准：关键调用点被误压，跨文件推理与长距离依赖上的压缩误差逐步累积，补全正确率下降，而错误表现为语义漂移而非崩溃，排查成本高。第二类是非代码文本或动态生成内容的结构标注不稳定，区间类型标签错乱会让解码时按标签选精度的寻址失效，压缩 KV 与原始 KV 混读造成注意力结果不一致——这是最危险的一种，因为它在数值上不报错，只表现为输出前后矛盾。第三类是压缩不可逆带来的重预填代价：后续需要被驱逐内容时只能重新预填，在工具输出频繁回溯的循环里，这部分开销会以尖峰形式吃掉压缩省下的显存余量。工程判断上，应把「非结构化输入占比」与「工具输出回溯率」作为两个准入指标，任一偏高就退回均匀压缩或纯注意力驱逐，而不是硬套结构配方。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>结构信号</th><th>压缩收益</th><th>主要代价</th></tr></thead><tbody><tr><td>仓库级 agent 长会话</td><td>强，区间类型稳定</td><td>显存显著下降，签名与引用不丢</td><td>增量解析与重压缩开销</td></tr><tr><td>单文件短补全</td><td>中，区间少</td><td>有限</td><td>预处理摊不掉，首 token 时延上升</td></tr><tr><td>日志/自然语言为主</td><td>弱，标注不稳</td><td>低甚至为负</td><td>标签错乱致混读不一致</td></tr></tbody></table>\n<h3 id=\"alg-structural-kv-compress-sec-26\">二十六 · 硬件档位与压缩预算的耦合</h3>\n<p>结构化 KV 压缩的部署配方不能从“选一张卡”开始，而要从“压缩预算落在哪一层存储”开始。机制上，AST 区间标签决定了每个结构区间走原始精度还是压缩表示，而这两类表示在 Blackwell 上的驻留位置不同：关键区间（函数签名、调用点、异常栈）的原始 KV 需要保持可被 tcgen05 MMA 直接消费的布局，通常留在 HBM 的活跃页里；低密度区间（大段导入块、重复的日志行）压缩后的表示则可以下沉到更冷的页，甚至在容量吃紧时按块表元数据做换出。因此硬件档位的第一判断不是算力峰值，而是 HBM 容量与每 token 的 KV 字节数之比——B200 单卡与 GB200 NVL72 机架在这一点上是两种不同的配方起点。</p>\n<p>预算分配沿用区间加权公式：</p>\n<div class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</div>\n<p>部署时把 $B$ 固定为“本档位可用的 KV 显存上限”，反解出每个区间的 $r_i$ 下限，就得到该档位的压缩率基线。工程代价直接体现在带宽上：高密度区间取 $r_i\\approx 1$ 意味着解码时这些块按原始位宽读取，注意力读取带宽不会被统一解压放大；低密度区间压缩后读取字节数下降，但需要一次解压或反量化再进 MMA，这部分算力开销落在 SM 的向量单元而非 Tensor Core 上。一个具体例子：agent 编码循环里，一个 200 行的工具输出日志块被标为低密度、$r_i$ 压到 1/4，而同一轮里被引用的三个函数签名保持原始精度——解码时前者省下的是 HBM 读带宽，后者省下的是重算预填的代价。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-27\">二十七 · 并行拓扑：结构区间与 TP/EP 的切分对齐</h3>\n<p>并行拓扑的选择受一个约束支配：结构区间的 KV 不能跨 TP rank 被切碎到无法按标签寻址。机制上，块表元数据记录区间类型与压缩率，解码时注意力按标签寻址；如果张量并行把同一个函数区间的 KV 头切到不同 rank，那么“关键区间走原始 KV”这条规则就退化成每个 rank 各自判断，元数据一致性维护成本上升。配方上的做法是让 TP 切分沿注意力头维度进行，而结构区间标签在块表层面全局一致——每个 rank 持有同一区间的不同头切片，但压缩率 $r_i$ 由全局密度打分统一决定，不允许 rank 间漂移。</p>\n<p>对 GB200 NVL72 这类机架级部署，NVLink 5 域内的高带宽使得跨 rank 的块表同步不是瓶颈，真正要控制的是增量重压缩的触发面。第五步增量更新只对受影响区间重新压缩并回写块表，若并行拓扑把一次工具输出的结构区间打散到多个 rank，重压缩的同步点数量随 rank 数增长。工程判断是：把结构区间的边界尽量对齐到单 rank 内的连续块，使一次工具输出触发的重压缩落在少数 rank 上；EP（专家并行）场景下则相反，MoE 层的 KV 与结构区间无强耦合，可以按专家切分自由布局，把结构标签寻址留给注意力层。</p>\n<p>代价量化在首 token 时延上：AST 解析与区间打分是预处理阶段的串行工作，并行拓扑不能加速它，只能通过把解析任务按文件/工具输出分片到不同 rank 的 host 侧来摊薄。长会话中每次工具输出后都要增量执行，若解析开销超过压缩带来的显存收益，TTFT 反而上升——这是配方必须设一个“增量压缩收益阈值”的原因。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-28\">二十八 · 量化方案：按区间分层的精度档位</h3>\n<p>量化档位不是全局一个数，而是按区间密度分层。机制上，第二步按区间信息密度打分，高分区间保留原始精度，低分区间按块执行 KV 合并或低比特量化；这与 Blackwell 的 NVFP4/FP8 路径直接对接——低密度区间的 KV 可以走 FP8 甚至 NVFP4 的块量化，高密度区间维持 BF16/FP16 原始表示。关键点在于“块为单位”：量化粒度必须与分页块表对齐，否则解码时按标签选精度会退化成逐元素判断，寻址开销吃掉带宽收益。</p>\n<p>公式上，区间压缩率与位宽的映射可以写成 $r_i = w_{\\text{orig}} / w_i$，其中 $w_i$ 是该区间选用的位宽；密度打分 $f$ 的输出直接落到离散档位集合上（原始、FP8、NVFP4、合并驱逐），而不是连续值，这样块表元数据只需存档位编号，元数据本身的开销可控。一个具体例子：导入块与被引用标识符所在的区间取原始精度，因为标识符一旦被量化误差污染，跨文件引用解析就会失真；而重复出现的错误栈尾部取 NVFP4，因为它的语义已被栈顶帧覆盖。</p>\n<p>系统代价分两侧：低比特区间省显存与读带宽，但反量化在 MMA 前引入额外向量指令，若低密度区间占比过高，SM 的向量单元成为新瓶颈；高精度区间保质量，但显存占用不降。稳定性技巧是按任务校准阈值——跨文件推理与长距离依赖上压缩误差会累积，需按仓库任务而非单文件设定密度阈值与最低保留精度，否则关键调用点被误压后补全正确率下降且难以定位。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-29\">二十九 · KV 策略：与分页块表共用一套寻址</h3>\n<p>KV 策略的核心是与现有分页 KV 管理共用块表，在 serving 栈上增量实现。机制第三步把压缩后的 KV 写入分页块表，元数据记录区间类型与压缩率；第四步解码按结构标签选择读取精度，关键区间走原始 KV，其余走压缩表示，注意力寻址由元数据驱动，避免对全部 KV 统一解压带来的带宽回涨。这条设计与分页块管理的块表结构同构，差别只在元数据多了区间类型与档位两个字段——分页块表管理本身不在本片段展开。</p>\n<p>策略参数上要定三件事：块大小、压缩触发水位、驱逐顺序。块大小应与 AST 区间的典型长度匹配，太小则元数据开销占比上升、区间标签碎片化；太大则一个区间内的密度差异被平均掉，高密度 token 被低密度邻居拖累。压缩触发水位按显存余量设定，接近上限时才启动低密度区间的合并或量化，避免无谓的预处理。驱逐顺序由结构重要性决定而非 LRU：被引用标识符与控制流关键字所在的锚点 token 最后驱逐，这与“块内保留锚点 token 的 KV”一致。</p>\n<p>不可逆性是这条策略的硬约束：压缩后若后续需要被驱逐内容，只能重新预填。因此配方上要给“可能被再次引用”的区间留一个最低保留精度，宁可多占一点显存也不做彻底驱逐；在 agent 循环里，工具输出往往在几轮后被再次引用，彻底驱逐的重新预填代价会以 TTFT 尖峰的形式出现。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-30\">三十 · 调度参数：增量压缩与批处理的时序咬合</h3>\n<p>调度层要解决的是增量压缩与连续批处理的时间冲突。机制第五步：新工具输出到达时增量更新结构标注，只对受影响区间重新压缩并回写块表，未受影响区间的压缩 KV 保持不变。落到调度参数上，这意味着每个请求有一个“结构版本”状态：解析完成、打分完成、块表回写完成三个阶段各自可被调度器观测，只有块表回写完成的区间才允许进入解码批次。若把未完成回写的区间混入批次，解码时按标签寻址会读到旧压缩表示，注意力结果不一致。</p>\n<p>批调度参数上，预处理与解码的资源竞争要显式隔离：AST 解析与区间打分吃 host CPU 与部分 SM，解码吃 Tensor Core 与 HBM 带宽，二者在同一批次窗口内争抢会让 decode 的 ITL 抖动。配方做法是给预处理设独立的并发上限，并在批次组装时优先保证已有请求的 decode 连续性——新请求的压缩预处理可以排队，已在解码的请求不因新工具输出到达而被抢占。一个具体例子：一个长会话 agent 在第 N 轮收到大段工具输出，调度器先让该请求的受影响区间完成增量压缩与块表回写，再把它并入下一批 decode，而不是立即插入当前批。</p>\n<p>吞吐代价体现在批次有效 token 数上：增量压缩期间该请求不产生 decode token，等效于批次里出现空洞。控制手段是压缩粒度——按区间而非按整段上下文重压缩，把空洞宽度压到单个区间级别；同时把密度阈值校准放在离线任务画像阶段完成，线上只做查表式打分，减少每次工具输出后的预处理工作量。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-31\">三十一 · 可复现的配置思路：从任务画像反推档位</h3>\n<p>把上述五节收束成一条可复现的配置路径，顺序是任务画像 → 预算反解 → 档位选择 → 参数校准，而不是先选硬件再调算法。第一步任务画像：统计仓库上下文的 AST 区间类型分布、工具输出的非代码文本占比、跨文件引用的平均距离。非结构化输入占比高时结构信号弱，收益下降，这条画像直接决定是否启用结构化压缩而非退回均匀策略。</p>\n<p>第二步预算反解：用区间加权公式把目标显存上限 $B$ 摊到各区间类型上，得到每类区间的压缩率基线；第三步档位选择：按基线把区间类型映射到原始/FP8/NVFP4/合并四档，并检查低密度区间占比是否会让反量化成为向量单元瓶颈；第四步参数校准：块大小对齐 AST 区间典型长度，压缩触发水位按显存余量设定，密度阈值按仓库任务校准而非单文件，锚点 token 的驱逐顺序固定为最后。</p>\n<p>失败模式要在配方里前置成检查项：AST 解析与区间打分在每次工具输出后增量执行，长会话中预处理开销可能超过压缩带来的显存收益，导致 TTFT 反而上升——用增量压缩收益阈值拦截；非代码文本或动态生成内容的结构标注不稳定，区间类型标签错乱会使解码按标签选精度的寻址失效，压缩 KV 与原始 KV 混读造成注意力结果不一致——用标签置信度下限拦截，低于下限的区间退回统一精度。配置的可复现性最终落在块表元数据的两个字段上：区间类型与档位编号，它们是整套配方在 serving 栈上可被观测、可被回放的最小状态。</p>\n<h3 id=\"alg-structural-kv-compress-sec-32\">三十二 · 显存账：压缩率不是均匀红利</h3>\n<p>结构化 KV 压缩在系统账本上的第一笔开销是显存，但它的收益分布并不均匀。按 AST 区间分配预算时，总显存由 <span class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|$$</span> 决定，其中 <span class=\"formula\">$$|K_i|$$</span> 是第 <span class=\"formula\">$$i$$</span> 个结构区间的 KV 元素数，<span class=\"formula\">$$r_i=f(\\text{density}_i)$$</span> 把区间信息密度映射为压缩率。工程上必须意识到：函数签名、控制流关键字、被引用标识符所在的高密度区间取 <span class=\"formula\">$$r_i\\approx 1$$</span>，几乎不省显存；真正被压掉的是导入块、大段工具输出、日志尾部这类低密度区间。因此整条会话的有效压缩率不是某个常数，而是各区间元素数的加权平均，权重偏向长尾低密度块时才好看。</p>\n<p>这带来一个直接的容量规划判断：仓库级 agent 会话里，KV 的绝对体积主要由工具输出和文件正文贡献，而这些恰恰是低密度区间，所以显存下降幅度在“工具输出占比高”的负载上最明显；反过来，多轮对话密集、每轮只改几行代码的负载，高密度区间占比上升，压缩收益迅速收窄。分页块表在这里是承重结构——压缩后的 KV 以块为单位写入，元数据记录区间类型与压缩率，块粒度决定了显存碎片的下限。块划得粗，低密度区间被迫与高密度区间共享同一压缩率，显存账立刻失真；块划得细，元数据本身又占显存。这个权衡与分页 KV 块管理是同一套账，只是压缩给它加了一维“精度标签”。</p>\n<p>具体例子：一个 agent 循环里，仓库上下文含数十个函数块，工具输出是编译错误栈。错误栈区间信息密度高（调用点、行号、符号名），按 <span class=\"formula\">$$r_i\\approx 1$$</span> 保留；函数体内部低密度区间按块合并。若把错误栈误判为低密度而压掉，显存是省了，但下一轮修复的跨文件推理直接失真——这是压缩不可逆的代价，需要时只能重新预填，显存省下来的部分被重算的预填成本吃掉。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-33\">三十三 · 带宽账：解码寻址不能引发解压回涨</h3>\n<p>显存只是静态容量，解码阶段的真瓶颈是 HBM 带宽。结构化压缩的设计要点在于：注意力按结构标签选择读取精度，关键区间走原始 KV，其余区间走压缩表示，寻址由块表元数据驱动。如果实现成“先把整段 KV 统一解压再算注意力”，带宽立刻回涨到未压缩水平，压缩在显存上赚的全部利润被解码读放大抵消。正确做法是让解压发生在块加载路径上，按块粒度只解当前注意力窗口命中的区间。</p>\n<p>代价可以写成读放大的形式：设压缩后每块字节数为 <span class=\"formula\">$$s_i$$</span>、原始为 <span class=\"formula\">$$S_i$$</span>，则解码一个 token 的 KV 读取量为 <span class=\"formula\">$$\\sum_{i\\in \\text{window}} s_i + \\text{meta}$$</span>，只有当窗口内高密度区间占比低时，这个和才显著小于 <span class=\"formula\">$$\\sum S_i$$</span>。换言之，带宽收益与显存收益同源但不同步：显存看全序列，带宽只看当前解码步实际触达的区间。长上下文解码时注意力窗口覆盖大量低密度块，带宽收益明显；短上下文或高密度区间集中在前部时，带宽几乎不降。</p>\n<p>工程判断落在块表元数据的布局上。元数据要能在不加载 KV 本体的前提下判定区间类型与压缩率，否则每次寻址都要先读元数据再读块，形成两级访存。把区间标签与压缩率压进块表项、与块指针同 cacheline，是让寻址开销沉入流水线的关键。这与分页块表管理的元数据设计共用同一套结构，压缩只是多写了两个字段。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-34\">三十四 · 通信账：分离式部署下的压缩不对称</h3>\n<p>在预填/解码分离的部署里，KV 要跨节点搬运，通信量直接由压缩后的字节数决定。结构化压缩在这里制造了一个不对称：预填节点做 AST 解析、区间打分、压缩写入，产出的是压缩 KV 与块表元数据；解码节点按标签寻址读取。跨节点传输的是压缩表示，因此 NVLink 或 RDMA 上的 KV 搬运量随压缩率下降——这是压缩在通信账上的正收益，且在高密度区间少的负载上最明显。</p>\n<p>但不对称的另一面是重压缩的通信代价。多轮 agent 循环中新工具输出到达，增量更新只对受影响区间重新压缩并回写块表，未受影响区间的压缩 KV 保持不变。问题在于“受影响区间”的判定：一个新工具输出可能改变跨块引用关系，使原本低密度的区间升级为高密度，需要从压缩表示恢复为原始精度。恢复意味着重新预填该区间并回传，这部分通信量与压缩省下的量方向相反。规模上去后，增量重压缩的触发频率随工具调用次数线性增长，而每次触发的区间集合取决于引用图的变化范围，不是常数。</p>\n<p>具体例子：一个跨文件重构任务，agent 连续调用搜索、读文件、改文件三类工具。每次改文件都让被改函数的调用点区间密度上升，触发局部恢复。若块表按文件粒度组织，一次改动可能波及多个文件的引用块，恢复集合被放大；若按 AST 区间粒度组织，恢复集合收敛到真正变化的块，通信量可控。这就是压缩单元选择在通信账上的直接体现——压缩单元是 AST 区间块而非单 token，粒度决定了增量传播的范围。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-35\">三十五 · 功耗与预处理：AST 开销是隐形税</h3>\n<p>结构化压缩把成本从解码侧挪到了预处理侧。AST 解析、区间信息密度打分、跨块引用关系统计，都在每次输入变化时执行。解码侧省下的是 KV 读取带宽与显存占用，预处理侧付出的是 CPU/GPU 算力与功耗。在功耗受限的整机柜部署里，这笔账不能只看解码吞吐：预处理功耗若与解码功耗同量级，整机 perf/watt 的改善远小于吞吐数字暗示的幅度。</p>\n<p>关键是预处理开销随上下文长度与工具输出量的增长方式。AST 解析对代码是近线性于 token 数，但区间打分里的跨块引用关系需要构建引用图，最坏情况下随块数超线性。长会话中每次工具输出都触发增量解析与增量打分，累计预处理时间可能超过压缩带来的显存收益所折算的解码加速——这正是失败模式里“首 token 时延反而上升”的来源。首 token 时延（TTFT）对预处理最敏感，因为压缩必须在预填完成前落地，解码才能按标签寻址。</p>\n<p>缓解手段是增量化的边界控制：只对受影响的 AST 子树重新解析，引用图只更新变化节点的入边与出边，未受影响区间的压缩 KV 与元数据原地不动。这把每次工具输出的预处理成本从“全上下文”压到“变化子图”，但要求块表能按区间定位并支持局部回写。工程上还要给预处理设预算上限：当增量解析的预估开销超过阈值时，退化为不压缩直接预填，用显存换时延——这是一个显式的降级开关，而不是让预处理无界膨胀。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-36\">三十六 · 尾延迟：压缩误差累积与寻址失效</h3>\n<p>吞吐是均值，尾延迟才是 SLO 的真约束。结构化压缩在尾部的风险有两个来源。其一是压缩误差在跨文件推理与长距离依赖上累积：密度阈值若按单文件校准而未按仓库任务校准，关键调用点被误压，模型输出质量下降但不报错，表现为补全正确率下滑且难以定位——这类失败不体现在延迟数字上，却体现在重试与人工介入带来的有效尾延迟上。其二是寻址失效：非代码文本或动态生成内容的结构标注不稳定，区间类型标签错乱，解码时按标签选精度的寻址把压缩 KV 与原始 KV 混读，注意力结果不一致，个别请求出现异常长的解码步或重复生成。</p>\n<p>尾延迟的放大机制在于压缩不可逆。一旦某区间被驱逐，后续需要时只能重新预填，而重新预填发生在解码中途，直接把该请求的 TPOT 拉出一个尖峰。规模上去后，尖峰出现的频率随会话长度与工具调用密度上升，P99 被这些重预填事件主导。容量规划必须把重预填概率计入，而不是只按压缩后的平均显存占用配卡。</p>\n<p>稳定性技巧是压缩阈值按任务校准：跨文件推理任务用更保守的密度阈值与更高的最低保留精度，单文件补全可以更激进。阈值不是全局常数，而是任务类型的函数。工程上把阈值与最低保留精度写进块表元数据的策略字段，让同一集群内不同任务走不同压缩档位，避免一套阈值打天下导致的尾部劣化。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-37\">三十七 · 规模上去先崩哪里</h3>\n<p>把五本账放在一起，规模上升时最先崩的不是显存，而是预处理与增量重压缩的耦合。显存随压缩率线性下降，是可预测的；预处理开销随工具输出次数与会话长度累积，是超线性的；两者在长会话里交叉，压缩省下的显存折算成可容纳的并发会话数，被预处理占用的算力与首 token 时延抵消。第二个崩点是尾延迟：重预填事件的频率随规模上升，P99 由这些事件定义，均值吞吐再好看也救不了 SLO。</p>\n<p>判断依据可以写成一个粗略的盈亏条件：设单次增量压缩开销为 <span class=\"formula\">$$c_p$$</span>、压缩带来的单请求解码节省为 <span class=\"formula\">$$c_d$$</span>、会话内工具调用次数为 <span class=\"formula\">$$n$$</span>，则净收益为正要求 <span class=\"formula\">$$n\\cdot c_p &lt; c_d + \\Delta\\text{capacity}$$</span>，其中 <span class=\"formula\">$$\\Delta\\text{capacity}$$</span> 是显存节省折算的并发增益。当 <span class=\"formula\">$$n$$</span> 大、<span class=\"formula\">$$c_p$$</span> 因引用图扩大而上升时，不等式右侧追不上左侧，压缩从收益变成税。这不是定性担忧，而是部署时必须实测的两个量：增量压缩的实际耗时分布，以及重预填事件的到达率。</p>\n<p>因此规模化的工程落点是两条：其一，把压缩单元钉在 AST 区间块上，让增量传播范围收敛，避免块粒度粗化导致的恢复集合放大；其二，给预处理设硬预算并保留降级路径，在工具输出密集的会话里主动放弃压缩、直接预填，用显存换首 token 时延。压缩不是无条件正确的优化，它在结构化输入占比高、工具调用稀疏的负载上是净收益，在非结构化输入占比高、工具调用密集的负载上要先算清 <span class=\"formula\">$$n\\cdot c_p$$</span> 与 <span class=\"formula\">$$c_d$$</span> 的比值再决定是否开启。</p>\n<h3 id=\"alg-structural-kv-compress-sec-38\">三十八 · 精度失败：阈值校准错位与结构标签失效</h3>\n<p>结构化 KV 压缩的精度问题几乎不来自压缩算子本身，而来自<strong>预算分配的判据错位</strong>。核心公式 $B=\\sum_i r_i\\cdot|K_i|,\\ r_i=f(\\text{density}_i)$ 里，$f$ 把区间信息密度映射为压缩率；一旦 $\\text{density}_i$ 的估计偏了，$r_i$ 就会在错误的区间上取到接近 1 或接近下限。工程上最常见的两种错位：其一，密度阈值按单文件校准，而实际负载是仓库级跨文件推理，导入块、调用点这类“自身 token 少、被引用次数多”的区间被打成低密度，$r_i$ 被压到低比特甚至驱逐，跨文件依赖链断掉；其二，非代码文本（日志、工具输出的自然语言、动态生成的片段）AST 解析失败或退化为粗粒度区间，区间类型标签错乱，解码时按标签选精度的寻址路径失效，压缩 KV 与原始 KV 混读，注意力结果前后不一致。</p>\n<p>诊断这类问题不能只看端到端正确率，要构造<strong>可归因的探针</strong>。做法是：在压缩前后各跑一次同一批“结构敏感”用例——跨文件符号引用补全、错误栈回溯修复、签名变更后的调用点改写——把失败样本按区间标签分组统计。若失败集中在某一类标签（例如 import 块或调用点），说明该类区间的 $f$ 映射过激；若失败样本的标签分布与基线一致，则问题更可能在块内锚点 token 的保留策略上。另一个低成本探针是<strong>混读一致性检查</strong>：对同一段上下文分别用“全原始 KV”和“压缩 KV”解码同一 query，比较 top-k logits 的秩相关性；相关性在特定结构边界处骤降，即定位到标签寻址失效的区间。</p>\n<p>代价上，这类精度退化是<strong>静默的</strong>：显存与吞吐指标全部正常，只有任务成功率下滑，且因为压缩不可逆，被驱逐区间的内容无法回读，只能重新预填。因此阈值必须按任务类型校准并留出安全边际——跨文件推理任务应把最低保留精度抬高、把高引用区间的 $r_i$ 钉在接近 1，宁可牺牲一部分显存收益。回滚手段是版本化阈值配置：把密度阈值、最低保留精度、锚点 token 集合作为一组可寻址的配置项随块表元数据一起落盘，发现精度下滑时切回上一组配置并对受影响会话触发重预填，而不是全局回退整个 serving 栈。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-39\">三十九 · OOM 与批抖动：预算公式与真实占用脱节</h3>\n<p>OOM 在结构化压缩场景里通常不是“压缩没生效”，而是<strong>预算账本与实际占用不一致</strong>。$B=\\sum_i r_i|K_i|$ 是静态预算，但真实占用还包含：块表元数据（区间类型、压缩率、锚点索引）、压缩表示的粒度对齐填充、以及增量更新时“新旧两份区间短暂共存”的峰值。多轮 agent 循环里，新工具输出到达触发增量压缩，受影响区间重写块表期间，旧压缩块尚未释放、新块已分配，峰值占用可达稳态的倍数级。若容量规划只按稳态 $B$ 做，长会话必然撞墙。</p>\n<p>批抖动是 OOM 的近亲：连续批处理下，不同请求的压缩率分布差异极大——一个仓库级长会话请求可能因高密度区间多而实际占用远超其 token 数所暗示的份额，而一个短对话请求占用极低。若调度器按 token 数估算显存，就会出现“大请求挤爆、小请求空转”的抖动：批内某请求触发抢占或重算，整批的 decode 步被拖慢，吞吐呈锯齿状。诊断信号是<strong>批内占用方差</strong>与<strong>抢占次数</strong>：把每步的批占用按请求拆开记录，方差持续偏高说明准入控制用的估算模型失真。</p>\n<p>工程判断：准入控制应以“压缩后实际块数”而非原始 token 数计价，调度器读取块表元数据里的压缩率来估算占用；对增量压缩的峰值，预留一段显式的高水位余量，并在重压缩期间对新请求做软限流而非硬拒绝。回滚路径是降级压缩策略——把部分区间的 $r_i$ 抬回 1（即放弃压缩）换取确定性占用，这在尾延迟敏感时段比触发抢占更划算。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-40\">四十 · 路由不均与尾延迟尖刺</h3>\n<p>结构化压缩把 KV 切成带标签的区间，解码时按标签寻址，这天然引入<strong>非均匀的访存路由</strong>：关键区间走原始精度、低密度区间走压缩表示，两类读取的带宽与延迟特征不同。当一批请求的关键区间比例差异大时，SM 上的访存负载不均，部分 CTA 长时间等待高精度区间的原始 KV 读取，形成尾延迟尖刺。更隐蔽的一种：区间标签在增量更新后发生漂移（新工具输出改变了某区间的类型判定），块表元数据被改写，正在解码的请求遇到“标签已变、块未换”的中间态，触发一次额外的同步等待。</p>\n<p>诊断要看<strong>按区间标签拆分的解码步耗时分布</strong>，而不是只看请求级 P99。若尖刺集中在少数标签上，说明该标签对应的读取路径（原始精度 vs 压缩解压）成为瓶颈；若尖刺与增量更新事件在时间上相关，则是元数据改写引发的同步。另一个信号是块表寻址的命中率：标签错乱会导致寻址回退到保守路径（全解压），带宽回涨、延迟抬升，这与前文所述“避免对全部 KV 统一解压”的设计意图直接冲突。</p>\n<p>缓解手段是<strong>把重压缩移出关键路径</strong>：增量更新在独立的预处理流上完成，块表切换采用双缓冲——新块写满后再原子替换元数据指针，解码侧永远读到一致快照。对路由不均，可在批组装阶段按关键区间比例做搭配，避免一批里全是高精度重负载请求。代价是预处理流占用额外显存与算力，且双缓冲使峰值占用再抬一档，需与上一节的容量余量合并核算。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-41\">四十一 · 监控面：该埋哪些点</h3>\n<p>结构化压缩的可观测性要覆盖三层，缺一层就会在故障时无从归因。<strong>压缩层</strong>：每区间的标签、$\\text{density}_i$、$r_i$、压缩前后元素数，以及锚点 token 的保留命中率——这是判断阈值是否错位的直接证据。<strong>块表层</strong>：块表元数据版本、增量重压缩次数、双缓冲切换次数、寻址回退（保守全解压）比例。<strong>服务层</strong>：请求级 TTFT 与 TPOT 的 P50/P99、批内占用方差、抢占与重算次数、按标签拆分的解码步耗时。</p>\n<p>关键是要把三层用<strong>同一个请求标识</strong>串起来：一个尾延迟尖刺能下钻到它当时命中的区间标签与块表版本，才能区分“是压缩策略问题”还是“是调度搭配问题”。指标采集本身有代价——逐区间统计会在预处理阶段增加开销，长会话中这项开销可能超过压缩带来的显存收益，使首 token 时延反而上升；因此采样应分层：全量采集块表级计数（低成本），区间级明细按请求采样（如固定比例），并对预处理耗时单独设一条 SLO 线，超线即告警。</p>\n<p>告警阈值建议按“相对基线漂移”而非绝对值设定：寻址回退比例、批内占用方差、预处理耗时占比这三个指标对策略退化最敏感，且不依赖具体硬件档位。表格给出诊断对照：</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>首要怀疑</th><th>下钻指标</th><th>处置</th></tr></thead><tbody><tr><td>正确率静默下滑</td><td>密度阈值按单文件校准</td><td>按标签分组的失败率</td><td>切回上一版阈值配置，重预填受影响会话</td></tr><tr><td>OOM / 批抖动</td><td>准入按 token 计价，忽略压缩率与重压缩峰值</td><td>批内占用方差、抢占次数</td><td>改按块数计价，预留高水位，软限流</td></tr><tr><td>尾延迟尖刺</td><td>标签漂移或路由不均</td><td>按标签的解码步耗时、双缓冲切换次数</td><td>重压缩移出关键路径，批组装搭配</td></tr><tr><td>带宽回涨</td><td>标签错乱触发保守全解压</td><td>寻址回退比例</td><td>校验区间标签，修复解析退化路径</td></tr></tbody></table>\n\n<h3 id=\"alg-structural-kv-compress-sec-42\">四十二 · 回滚：不可逆压缩下的最小代价路径</h3>\n<p>结构化压缩的根本约束是<strong>压缩不可逆</strong>：被驱逐或被合并的 KV 无法还原，需要时只能重新预填。这决定了回滚不能设计成“撤销压缩”，而必须设计成“切换到保守策略 + 定向重预填”。最小代价路径有三条，按代价递增排列。第一条，<strong>策略级回滚</strong>：切换阈值配置与最低保留精度，只影响新进入上下文的区间，已压缩区间保持不变——代价是旧会话仍带病运行，适合精度问题尚未定位时的止血。第二条，<strong>会话级重预填</strong>：对失败率超线的会话标识，丢弃其压缩 KV、按保守配置重新预填——代价是一次完整的 prefill 延迟与显存峰值，但影响面被隔离在单会话。第三条，<strong>全局回退</strong>：停用结构化压缩、退回均匀或纯注意力驱逐——代价是显存占用回升、长会话可能直接放不下，只在解析链路整体失效（如上游代码格式突变导致 AST 解析大面积失败）时使用。</p>\n<p>回滚要能快速执行，前提是<strong>配置与块表元数据同版本落盘</strong>，且预处理流与解码流解耦，使得切换配置不需要重启 serving 栈。另一个工程判断：把“压缩是否启用”做成按请求可选的开关，而不是全局二进制开关，这样在灰度期可以让高风险任务（跨文件修复、长错误栈回溯）走保守路径，低风险任务（单文件补全）走激进压缩，用任务类型而非全局指标来决定回滚粒度。</p>\n<p>最后落在具体机制上：回滚触发点应绑定在<strong>按标签分组的失败率</strong>这一指标上，而非端到端正确率——后者噪声大、定位慢；前者直接指向 $f(\\text{density}_i)$ 映射的哪一段出了问题，使回滚从“猜”变成“改一个映射区间”。这也解释了为什么监控面必须把区间标签作为一等维度：没有标签维度，回滚只能全局化，代价就是整段长会话的重预填。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-43\">四十三 · 结构化压缩的失效边界与回滚判据</h3>\n<p>这套方案最脆弱的环节不在压缩本身，而在每次工具输出后都要增量执行的 AST 解析与区间打分。长会话里，预处理开销会随上下文长度和工具调用次数线性叠加，一旦它超过压缩节省的显存与带宽收益，首 token 时延反而上升——这是最典型的“越优化越慢”失败模式。诊断上应把预处理耗时与压缩后注意力读取耗时分开打点，用 <span class=\"formula\">$$T_{\\text{pre}}/T_{\\text{attn}}$$</span> 作为健康度指标；该比值持续走高即说明结构统计已成为瓶颈，此时应退化为仅对新增区间做惰性标注，或对低密度区间直接走块级量化而跳过精细打分。</p>\n<p>第二类失效是精度问题，且难以定位。压缩误差在跨文件推理与长距离依赖上累积，若密度阈值按单文件校准而非按仓库任务校准，关键调用点会被误压，补全正确率下降却不报错。可用一个可观测的代理指标：统计解码时命中“关键区间原始 KV”的注意力质量占比 <span class=\"formula\">$$\\rho=\\frac{\\sum_{i\\in\\text{key}}|K_i|}{\\sum_i r_i|K_i|}$$</span>，$\\rho$ 异常偏低意味着预算被低密度区间吃掉。回滚策略是保留最近一次压缩前的块表快照，按区间粒度而非全局回退，只把被误压的调用点区间恢复原始精度。</p>\n<p>第三类是寻址一致性故障：非代码文本或动态生成内容的结构标注不稳定，区间类型标签错乱会让解码时按标签选精度的寻址失效，压缩 KV 与原始 KV 混读直接造成注意力结果不一致，表现为批内个别请求输出崩坏而其余正常——这正是批抖动与尾延迟尖刺的来源之一。监控应在块表元数据上校验标签与压缩率的配对合法性，非法配对即触发该请求的隔离重预填。路由不均则表现为不同结构区间压缩率方差过大，可用区间压缩率的变异系数做告警阈值。需牢记压缩不可逆，被驱逐内容只能重新预填，因此回滚成本按重预填 token 数计，必须纳入容量规划。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>根因</th><th>处置</th></tr></thead><tbody><tr><td>首 token 时延上升</td><td>预处理开销超过收益</td><td>惰性标注或跳过打分</td></tr><tr><td>补全正确率下降</td><td>阈值未按仓库校准</td><td>区间级恢复原始精度</td></tr><tr><td>批内个别崩坏</td><td>标签错乱致混读</td><td>隔离并重预填该请求</td></tr></tbody></table>\n<h3 id=\"alg-structural-kv-compress-sec-44\">四十四 · 对照轴：压缩单元、决策依据与不可逆性</h3>\n<p>把结构化 KV 压缩放进同族算法的坐标系，先要确定三条对照轴，否则“选哪个”会退化成偏好之争。第一条轴是<strong>压缩单元</strong>：本算法以 AST 区间块为单位，分页 KV 块管理以固定 token 块为单位，纯注意力驱逐以单 token 为单位，前缀缓存复用则以整棵基数树的共享前缀为单位。单元越大，元数据越少、块表越简单，但对结构边界的敏感度越高；单元越小，粒度越细，寻址与元数据开销越大。第二条轴是<strong>决策依据</strong>：本算法用结构类型标签加区间信息密度，注意力驱逐用累计注意力质量，选择性检索用查询与仓库片段的相关性，前缀缓存用前缀哈希命中。第三条轴是<strong>可逆性</strong>：本算法的压缩不可逆，被驱逐内容只能重新预填；前缀缓存复用是可逆的（原始 KV 仍在池中）；检索门控根本不把内容放进上下文，因此谈不上逆。</p>\n<p>这三条轴组合出的判断很直接：当上下文的主要成分是代码与工具输出、且跨文件结构依赖是质量瓶颈时，按结构分配预算的收益超过按注意力分数分配；当上下文以自然语言日志为主、结构信号弱时，本算法的区间打分退化为噪声，反而不如均匀量化加纯注意力驱逐稳。工程上要警惕的是把“结构”当成万能标签——AST 解析只在可解析输入上成立，动态生成代码片段与半结构化日志会让区间类型标签错乱，解码时按标签选精度的寻址随之失效，压缩 KV 与原始 KV 混读造成注意力结果不一致。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-45\">四十五 · 与分页 KV 块管理的关系：共用块表，不共用预算逻辑</h3>\n<p>本算法与分页 KV 块管理不是竞争关系，而是分层关系。分页块管理解决的是“KV 放在哪、怎么按块寻址、块如何复用与回收”，本算法解决的是“每个块里保留多少精度、哪些 token 必须留原始 KV”。机制上，压缩后的 KV 写入分页块表，元数据记录区间类型与压缩率，解码时注意力按结构标签寻址；这与现有分页 KV 管理兼容，可在 serving 栈上增量实现。换句话说，块表是承载层，结构标签是策略层，二者通过元数据字段耦合。</p>\n<p>代价分工也很清楚：分页块管理引入的是块表查询与碎片化开销，量级在寻址路径上；本算法引入的是 AST 解析与区间打分的预处理开销，量级在首 token 时延上。两者叠加时，预处理开销不会因为共用块表而消失。长会话中每次工具输出到达都要增量执行结构标注与重压缩，若单次工具输出触发的受影响区间过多，预处理成本可能超过压缩带来的显存收益，首 token 时延反而上升。判断阈值应落在“受影响区间占比”上：只对受影响区间重新压缩并回写块表、未受影响区间的压缩 KV 保持不变，是控制这笔开销的关键；若增量更新退化为全量重压缩，本算法在长 agent 循环里就失去了部署价值。</p>\n<div class=\"formula\">$$\\text{budget}_b=\\frac{B\\cdot w_b}{\\sum_{b'}w_{b'}},\\quad w_b=\\alpha\\cdot\\text{attn}_b+\\beta\\cdot\\text{ref}_b+\\gamma\\cdot\\text{size}_b^{-1}$$</div>\n<p>上式是块级预算分配的通用形式：注意力质量、跨块引用关系、块大小倒数三项加权。对本算法而言，$\\text{ref}_b$ 是区别于纯注意力驱逐的关键项——被引用标识符所在的块即使注意力分数不高，也必须保留原始精度，否则调用点被压掉后跨文件推理失真。对分页块管理而言，这个公式不参与其内部逻辑，它只负责按预算结果落块。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-46\">四十六 · 与注意力驱逐、选择性检索的边界</h3>\n<p>纯注意力驱逐与本算法的分歧不在“压不压”，而在“按什么排序”。注意力驱逐按累计注意力质量排序，保留高分 token；问题在于代码结构信息分布不均，函数签名、控制流关键字、错误栈的注意力分数未必高，但一旦被压掉，补全与修复质量下降且难以定位。本算法把排序依据换成结构重要性：块内保留锚点 token（签名、控制流关键字、被引用标识符）的 KV，其余按预算压缩或驱逐。代价是预处理多了一次 AST 解析与跨块引用统计，收益是长仓库上下文下补全正确率优于均匀或纯注意力驱逐。</p>\n<p>与选择性检索门控的边界更干脆：检索门控决定“是否把某段内容放进上下文”，本算法在已进入上下文的 KV 上分配精度，二者作用在不同阶段，可以串联——检索先筛掉无关仓库片段，结构压缩再在剩余上下文里做非均匀精度分配。串联时的系统代价要分开核算：检索侧付出的是召回率风险（漏检关键文件），压缩侧付出的是不可逆误差（误压关键调用点）。两者叠加时，误差来源难以归因，诊断上应先固定检索召回、再单独校准压缩阈值。</p>\n<p>一个具体例子：agent 在修复一个跨三个文件的调用链错误时，错误栈与调用点分布在低注意力区间。纯注意力驱逐会优先保留近期对话与高频 token，把错误栈压掉；本算法按区间类型把异常栈与调用点标为高密度区间，$r_i\\approx 1$ 保留原始精度，低密度的注释与重复日志走低比特。显存下降的同时，关键签名与引用不丢——这是结构信号带来的确定性收益，而非统计上的平均收益。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-47\">四十七 · 决策表：按输入构成与任务形态选型</h3>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选</th><th>理由与代价</th></tr></thead><tbody>\n<tr><td>仓库级长会话、跨文件依赖是质量瓶颈</td><td>结构化 KV 压缩</td><td>按 AST 区间分配预算，保留结构依赖；代价是解析与打分预处理、压缩不可逆</td></tr>\n<tr><td>上下文以自然语言日志、动态生成内容为主</td><td>均匀量化 + 注意力驱逐</td><td>结构标注不稳定，区间标签错乱会使按标签寻址失效</td></tr>\n<tr><td>多轮对话共享同一系统提示与仓库头</td><td>基数树前缀缓存复用</td><td>复用原始 KV，可逆、无压缩误差；与本算法串联时先复用再压缩</td></tr>\n<tr><td>上下文大部分与当前查询无关</td><td>选择性检索门控</td><td>不进入上下文即不占显存；漏检风险由召回率承担</td></tr>\n<tr><td>显存紧张但首 token 时延预算宽</td><td>结构化 KV 压缩</td><td>预处理开销可被时延预算吸收，显存收益确定</td></tr>\n<tr><td>首 token 时延敏感、工具输出高频到达</td><td>增量压缩 + 阈值放宽</td><td>只重压受影响区间；阈值过激会误压关键调用点</td></tr>\n</tbody></table>\n<p>决策表的使用方式是先看输入构成，再看时延预算。输入构成决定结构信号是否可信：可解析代码占比高，本算法的区间打分才有意义；非代码文本占比高时，结构标注不稳定，收益下降。时延预算决定预处理开销能否被吸收：AST 解析与区间打分在每次工具输出后都要增量执行，长会话中这笔开销是持续性的，不是一次性的。规模上限受此约束——上下文越长、工具输出越多，预处理与增量重压缩成本越高。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-48\">四十八 · 适用条件与阈值校准</h3>\n<p>适用条件可以收敛成三条可检验的判断。其一，输入可解析：代码与工具输出能被 AST 解析成函数、类、导入块等结构单元边界，区间类型标签可信。其二，结构依赖是质量瓶颈：跨文件引用、调用点、异常栈在任务中被实际使用，而不是仅作背景。其三，时延预算能吸收预处理：首 token 时延允许包含解析与打分开销，或增量更新能把受影响区间压到很小比例。</p>\n<p>阈值校准是部署成败的关键。压缩阈值按任务校准：跨文件推理与长距离依赖上压缩误差会累积，需按任务类型设定密度阈值与最低保留精度；若密度阈值按单文件校准而未按仓库任务校准，关键调用点会被误压，补全正确率下降且难以定位。稳定性技巧是把最低保留精度设为硬下限，密度阈值在其上浮动——高密度区间取 $r_i\\approx 1$，低密度区间走低比特，KV 以块为单位合并或量化。失败模式还包括非代码文本或动态生成内容的结构标注不稳定，此时应回退到均匀策略，而不是强行套用结构标签。</p>\n<p>与目标与草稿联合量化的对照也值得一句：后者压缩的是权重与草稿模型的数值精度，作用在模型侧；本算法压缩的是 KV 的保留预算，作用在上下文侧。两者可叠加，但误差来源不同，校准时应分开做消融，避免把补全质量下降归因到错误的环节。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-49\">四十九 · 工程判断：串联顺序与回退路径</h3>\n<p>多算法串联时的顺序影响代价结构。合理顺序是：前缀缓存复用先做（可逆、零压缩误差），选择性检索其次（缩小上下文），结构化 KV 压缩最后（在剩余上下文上分配精度）。反过来先压缩再检索，会让检索在压缩表示上做相关性判断，精度损失叠加且难以归因。串联的显存收益不是简单相加：前缀复用省下的是重复前缀的 KV，检索省下的是未进入上下文的部分，结构压缩省下的是已进入上下文中的低密度区间，三者作用域不重叠才有叠加意义。</p>\n<p>回退路径必须预先设计。压缩不可逆，后续需要被驱逐内容时只能重新预填——这意味着回退的代价是一次完整预填，在长仓库上下文下这笔代价可观。工程上应把“需要回退”的信号前置：当解码阶段出现对已压缩区间的异常高注意力、或工具输出引用了被驱逐的标识符时，触发重新预填而非继续在压缩 KV 上解码。这条判断落在具体机制上：元数据里的区间类型与压缩率是触发依据，块表是执行载体，增量更新逻辑是收尾手段。选型的最终依据不是算法优劣，而是输入构成是否让结构信号可信、时延预算是否让预处理开销可吸收、回退代价是否在可接受范围内。</p>\n\n<h3 id=\"alg-structural-kv-compress-sec-50\">五十 · 选型分水岭：结构信号强度与预处理预算</h3>\n<p>与同族算法对照，结构化 KV 压缩的独特性不在压缩算子本身，而在压缩单元的粒度：它把预算分配从单 token 注意力分数搬到 AST 区间上，用 <span class=\"formula\">$$B=\\sum_{i} r_i \\cdot |K_i|,\\quad r_i=f(\\text{density}_i)$$</span> 决定每个函数块、导入块、异常栈区间的压缩率，高密度区间取 <span class=\"formula\">$$r_i\\approx 1$$</span> 保留原始精度。这使它在仓库级长会话中优于均匀量化与纯注意力驱逐——后者会把函数签名、调用点连同噪声一起压掉，跨文件依赖随即失真。但代价是压缩前必须先付出一次 AST 解析与区间打分，且每次工具输出到达都要增量重做受影响区间。因此选型的第一道判据不是压缩率，而是<strong>结构信号强度</strong>：输入中代码与结构化工具输出的占比越高，区间标签越可信，寻址越稳；当日志、自然语言、动态生成内容占主导时，区间类型标签错乱会让解码按标签选精度失效，压缩 KV 与原始 KV 混读直接造成注意力结果不一致。此时应退回按 token 位置或注意力分数的方案，把结构压缩仅用于可解析的那部分上下文。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>结构化压缩</th><th>纯注意力/均匀压缩</th><th>检索门控</th></tr></thead><tbody><tr><td>代码占比高、跨文件引用密集</td><td>首选，签名与调用点不丢</td><td>关键结构易被误压</td><td>不解决已入上下文内的精度分配</td></tr><tr><td>非结构化文本为主</td><td>标签不稳定，收益下降</td><td>更稳</td><td>可作前置裁剪</td></tr><tr><td>工具输出高频、会话极长</td><td>增量重压缩开销需核算</td><td>预处理轻</td><td>减少入上下文量</td></tr><tr><td>需回读被驱逐内容</td><td>不可逆，只能重新预填</td><td>同样不可逆</td><td>可按需重新检索</td></tr></tbody></table>\n<p>第二道判据是<strong>预处理预算与首 token 时延的权衡</strong>。AST 解析与区间打分在每次工具输出后增量执行，长会话中这部分开销可能超过压缩省下的显存收益，表现为首 token 时延反而上升——这是该方案最典型的失效模式，尤其在 agent 编码循环里工具输出密集、单轮上下文增长快时。工程判断是：把增量压缩限制在受影响区间，未受影响区间的压缩 KV 与块表条目保持不变；同时按仓库任务而非单文件校准密度阈值，因为压缩误差会在跨文件推理与长距离依赖上累积，阈值过激时关键调用点被误压，补全正确率下降且难以定位。若会话长度尚未触及显存墙，结构压缩的预处理成本是纯亏损，应延后启用。</p>\n<p>第三道判据是<strong>可逆性需求</strong>。压缩不可逆，一旦后续推理需要被驱逐的块内容，只能重新预填，代价是一次完整的前向与显存重分配。若 agent 循环存在大量\"回看早期工具输出\"的模式，结构化压缩应与选择性检索门控组合：门控决定哪些内容进入上下文，结构压缩只在已进入上下文的 KV 上分配精度，两者职责不重叠。选型的收敛结论是——仓库级长会话、代码与结构化输出为主、显存或带宽已成瓶颈且能承担增量解析开销时，选结构化压缩；非结构化占比高、会话尚短、或需频繁回读被驱逐内容时，选更轻的均匀压缩加检索门控，把结构压缩留给真正需要保住签名的那些区间。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 仓库级上下文与KV复用</td></tr><tr><td>解决什么</td><td>agent 编码循环中仓库上下文、工具输出与多轮对话使 KV 极长，通用 KV 压缩按注意力分数丢弃会破坏代码结构依赖…</td></tr><tr><td>一句话机制</td><td>利用 AST 与代码块边界把 KV 按结构单元分组，按结构重要性而非单 token 注意力分数分配保留预算，块内保留关…</td></tr><tr><td>代价与失效</td><td>AST 解析与结构统计增加预处理开销，非代码文本（日志、自然语言）结构信号弱；压缩不可逆，后续需要被驱逐内容时只能重新预填</td></tr><tr><td>后继</td><td>语法栈约束解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-structural-kv-compress · 共 8 个片段</p>\n";break;}}})();
